WIKILINK_RE = re.compile(r"(?<!\!)\[\[([^\]]+)\]\]")
MARKDOWN_LINK_RE = re.compile(r"(?<!\!)\[[^\]]*\]\(([^)]+)\)")


@dataclass(frozen=True)
class FileRecord:
    path: Path
    relative_path: str
    extension: str
    size: int
    modified_at: str
    created_at: str
    top_level_area: str
    in_nested_subvault: bool


@dataclass(frozen=True)
